AL, AB, AT = '\\mathcal{A}_L', '\\mathcal{A}_B', '\\mathcal{A}_T'
PI = Dc('3.14')
def fm(x):
    x = Dc(x)
    s = format(x.quantize(Dc('0.0001')).normalize(), 'f')
    return s
def u(x, unit):
    if '^' in unit:
        b, e = unit.split('^'); return M(f'{x}\\ \\text{{{b}}}^{{{e}}}')
    return M(f'{x}\\ \\text{{{unit}}}')
def Wv(ans, cand, unit, k=3):
    ans = Dc(str(ans)); out = []
    for c in cand:
        c = Dc(str(c))
        if abs(c - ans) > Dc('0.0001') and c > 0 and c not in out: out.append(c)
    t = 1
    while len(out) < k:
        c = ans + t * (1 if t % 2 else -1) * max(Dc(1), ans / 10); t += 1
        if c > 0 and abs(c - ans) > Dc('0.0001') and c not in out: out.append(c)
    return [u(fm(c), unit) for c in out[:k]]
